// @ts-ignore `.open-next/worker.js` is generated by the OpenNext build
import { default as handler } from "./.open-next/worker.js";
import { drizzle } from "drizzle-orm/d1";
import type {
  DurableObjectState,
  ExportedHandler,
  WebSocket,
} from "@cloudflare/workers-types";
import * as schema from "./lib/db/schema";
import {
  publishDueDevotional,
  runDailyDevotional,
} from "./lib/devotionals/pipeline";
import { hashToken } from "./lib/auth/password";
import { SESSION_COOKIE } from "./lib/constants";

type SocketAttachment = { userId: string; conversationId: string };

declare const WebSocketPair: {
  new (): { 0: WebSocket; 1: WebSocket };
};

function readCookie(request: Request, name: string) {
  const cookie = request.headers.get("cookie") ?? "";
  for (const part of cookie.split(";")) {
    const [key, ...rest] = part.trim().split("=");
    if (key === name) return decodeURIComponent(rest.join("="));
  }
  return null;
}

async function authenticateSocket(
  request: Request,
  env: CloudflareEnv,
  conversationId: string,
) {
  const token = readCookie(request, SESSION_COOKIE);
  if (!token) return null;
  const sessionId = await hashToken(token);
  const session = await env.DB.prepare(
    `select u.id as userId, u.status as status, s.expires_at as expiresAt
     from sessions s join users u on u.id = s.user_id
     where s.id = ? limit 1`,
  )
    .bind(sessionId)
    .first<{ userId: string; status: string; expiresAt: number }>();
  if (!session || session.status !== "active" || Number(session.expiresAt) <= Date.now()) {
    return null;
  }
  const participant = await env.DB.prepare(
    `select 1 as ok from conversation_participants
     where conversation_id = ? and user_id = ? limit 1`,
  )
    .bind(conversationId, session.userId)
    .first<{ ok: number }>();
  if (!participant) return null;
  return session.userId;
}

function isSameOrigin(request: Request) {
  const origin = request.headers.get("origin");
  if (!origin) return false;
  try {
    const originUrl = new URL(origin);
    const requestUrl = new URL(request.url);
    const forwardedHost = request.headers.get("x-forwarded-host")?.split(",")[0]?.trim();
    return (
      originUrl.host === requestUrl.host ||
      Boolean(forwardedHost && originUrl.host === forwardedHost)
    );
  } catch {
    return false;
  }
}

export class RealtimeRoom {
  private state: DurableObjectState;

  constructor(state: DurableObjectState) {
    this.state = state;
  }

  private meta(ws: WebSocket): SocketAttachment | null {
    try {
      return ws.deserializeAttachment() as SocketAttachment | null;
    } catch {
      return null;
    }
  }

  private onlineUserIds() {
    return [
      ...new Set(
        this.state
          .getWebSockets()
          .map((ws) => this.meta(ws)?.userId)
          .filter((id): id is string => Boolean(id)),
      ),
    ];
  }

  private send(ws: WebSocket, payload: unknown) {
    try {
      ws.send(JSON.stringify(payload));
    } catch {
      /* The socket may already be closing. */
    }
  }

  private broadcast(payload: unknown, except?: WebSocket) {
    for (const ws of this.state.getWebSockets()) {
      if (ws !== except) this.send(ws, payload);
    }
  }

  async fetch(request: Request): Promise<Response> {
    const url = new URL(request.url);
    if (request.method === "POST" && url.pathname === "/broadcast") {
      try {
        const payload = await request.json();
        this.broadcast(payload);
        return Response.json({ ok: true, delivered: this.state.getWebSockets().length });
      } catch {
        return Response.json({ error: "Invalid broadcast payload." }, { status: 400 });
      }
    }

    if (request.headers.get("Upgrade")?.toLowerCase() !== "websocket") {
      return new Response("Expected a WebSocket upgrade.", { status: 426 });
    }
    const userId = request.headers.get("x-chat-user-id");
    const conversationId = request.headers.get("x-chat-conversation-id");
    if (!userId || !conversationId) {
      return new Response("Unauthorized.", { status: 401 });
    }

    const pair = new WebSocketPair();
    const client = pair[0];
    const server = pair[1];
    this.state.acceptWebSocket(server, [conversationId, userId]);
    server.serializeAttachment({ userId, conversationId } satisfies SocketAttachment);
    this.send(server, { type: "ready", online: this.onlineUserIds() });
    this.broadcast({ type: "presence", userId, online: true }, server);

    return new Response(null, {
      status: 101,
      webSocket: client,
    } as ResponseInit & { webSocket: WebSocket });
  }

  webSocketMessage(ws: WebSocket, message: string | ArrayBuffer) {
    if (typeof message !== "string") return;
    let payload: { type?: string; [key: string]: unknown };
    try {
      payload = JSON.parse(message) as { type?: string; [key: string]: unknown };
    } catch {
      return;
    }
    const meta = this.meta(ws);
    if (!meta) return;

    if (payload.type === "ping") {
      this.send(ws, { type: "pong", at: Date.now() });
      return;
    }
    if (payload.type === "typing") {
      this.broadcast(
        {
          type: "typing",
          userId: meta.userId,
          name: typeof payload.name === "string" ? payload.name.slice(0, 80) : "Someone",
          at: Date.now(),
        },
        ws,
      );
    }
  }

  webSocketClose(ws: WebSocket) {
    const meta = this.meta(ws);
    if (meta) {
      this.broadcast({ type: "presence", userId: meta.userId, online: false }, ws);
    }
  }
}

async function handleRealtime(request: Request, env: CloudflareEnv) {
  if (request.headers.get("Upgrade")?.toLowerCase() !== "websocket") {
    return new Response("Expected a WebSocket upgrade.", { status: 426 });
  }
  if (!isSameOrigin(request)) {
    return new Response("Request origin could not be verified.", { status: 403 });
  }
  const url = new URL(request.url);
  const conversationId = url.searchParams.get("conversationId");
  if (!conversationId) {
    return new Response("Missing conversation.", { status: 400 });
  }
  const userId = await authenticateSocket(request, env, conversationId);
  if (!userId) {
    return new Response("Unauthorized.", { status: 401 });
  }
  if (!env.REALTIME) {
    return new Response("Realtime is not configured.", { status: 503 });
  }

  const headers = Object.fromEntries(request.headers);
  headers["x-chat-user-id"] = userId;
  headers["x-chat-conversation-id"] = conversationId;
  const room = env.REALTIME.get(env.REALTIME.idFromName(conversationId));
  return room.fetch("https://realtime.internal/socket", {
    method: "GET",
    headers,
  });
}

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    if (url.pathname === "/api/realtime") {
      return handleRealtime(request as unknown as Request, env);
    }
    return handler.fetch(request, env, ctx);
  },
  async scheduled(_controller, env, ctx) {
    ctx.waitUntil(
      (async () => {
        const db = drizzle(env.DB, { schema });

        try {
          const result = await publishDueDevotional(db);
          console.log(
            "Daily Meal scheduled publish:",
            result.count,
            "published,",
            result.skipped,
            "skipped,",
            result.failed,
            "failed",
          );
          if (result.errors.length) {
            console.error("Daily Meal scheduled publish errors:", result.errors);
          }
        } catch (error) {
          console.error("Daily Meal scheduled publish error:", error);
        }

        try {
          const result = await runDailyDevotional({
            db,
            env,
            trigger: "cron",
          });
          if (result.status === "failed") {
            console.error("Daily Meal failed:", result.message);
          } else {
            console.log("Daily Meal:", result.status, result.message);
          }
        } catch (error) {
          console.error("Daily Meal schedule error:", error);
        }
      })(),
    );
  },
} satisfies ExportedHandler<CloudflareEnv>;
